import{_ as d,a0 as o,w as p,s as r,I as i,x as t,a1 as l,A as n,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"理解 Linux 鏈接（一） | LCTT x X-CMD","titleTemplate":false,"description":"理解 Linux 鏈接（一） | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"理解 Linux 鏈接（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"理解 Linux 鏈接（一） | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181018 Understanding Linux Links- Part 1","title":"理解 Linux 鏈接（一）","tag":"201810","desc":""},"relativePath":"201810/20181018 Understanding Linux Links- Part 1.md","filePath":"[post].md"}'),u={name:"201810/20181018 Understanding Linux Links- Part 1.md"};function g(b,s,k,h,x,f){const e=o("Link");return p(),r("div",null,[s[36]||(s[36]=i("h1",{id:"理解-linux-鏈接-一",tabindex:"-1"},[t("理解 Linux 鏈接（一） "),i("a",{class:"header-anchor",href:"#理解-linux-鏈接-一","aria-label":"Permalink to “理解 Linux 鏈接（一）”"},"​")],-1)),s[37]||(s[37]=i("blockquote",null,[i("p",null,"鏈接是可以將文件和目錄放在你希望它們放在的位置的另一種方式。")],-1)),s[38]||(s[38]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/linux-link-498708.jpg?itok=DyVEcEsc",alt:""})],-1)),i("p",null,[s[1]||(s[1]=t("除了 ",-1)),s[2]||(s[2]=i("code",null,"cp",-1)),s[3]||(s[3]=t(" 和 ",-1)),s[4]||(s[4]=i("code",null,"mv",-1)),s[5]||(s[5]=t(" 這兩個我們在",-1)),l(e,{href:"https://www.linux.com/blog/2018/8/linux-beginners-moving-things-around"},{default:n(()=>[...s[0]||(s[0]=[t("本系列的前一部分",-1)])]),_:1}),s[6]||(s[6]=t("中詳細討論過的，鏈接是可以將文件和目錄放在你希望它們放在的位置的另一種方式。它的優點是可以讓你同時在多個位置顯示一個文件或目錄。",-1))]),s[39]||(s[39]=a(`<p>如前所述，在物理磁盤這個級別上，文件和目錄之類的東西並不真正存在。文件系統是為了方便人類使用，將它們虛構出來。但在磁盤級別上，有一個名為<ruby>分區表<rt>partition table</rt></ruby>的東西，它位於每個分區的開頭，然後數據分散在磁盤的其餘部分。</p><p>雖然有不同類型的分區表，但是在分區開頭的那個表包含的數據將映射每個目錄和文件的開始和結束位置。分區表的就像一個索引：當從磁盤加載文件時，操作系統會查找表中的條目，分區表會告訴文件在磁盤上的起始位置和結束位置。然後磁盤頭移動到起點，讀取數據，直到它到達終點，您看：這就是你的文件。</p><h3 id="硬鏈接" tabindex="-1">硬鏈接 <a class="header-anchor" href="#硬鏈接" aria-label="Permalink to “硬鏈接”">​</a></h3><p>硬鏈接只是分區表中的一個條目，它指向磁盤上的某個區域，表示該區域<strong>已經被分配給文件</strong>。換句話説，硬鏈接指向已經被另一個條目索引的數據。讓我們看看它是如何工作的。</p><p>打開終端，創建一個實驗目錄並進入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir test_dir</span></span>
<span class="line"><span>cd test_dir</span></span></code></pre></div>`,6)),i("p",null,[s[8]||(s[8]=t("使用 ",-1)),l(e,{href:"https://www.linux.com/blog/2018/8/linux-beginners-moving-things-around"},{default:n(()=>[...s[7]||(s[7]=[t("touch",-1)])]),_:1}),s[9]||(s[9]=t(" 創建一個文件：",-1))]),s[40]||(s[40]=a(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch test.txt</span></span></code></pre></div><p>為了獲得更多的體驗（？），在文本編輯器中打開 <code>test.txt</code> 並添加一些單詞。</p><p>現在通過執行以下命令來建立硬鏈接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln test.txt hardlink_test.txt</span></span></code></pre></div><p>運行 <code>ls</code>，你會看到你的目錄現在包含兩個文件，或者看起來如此。正如你之前讀到的那樣，你真正看到的是完全相同的文件的兩個名稱： <code>hardlink_test.txt</code> 包含相同的內容，沒有填充磁盤中的任何更多空間（可以嘗試使用大文件來測試），並與 <code>test.txt</code> 使用相同的 inode：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -li *test*</span></span>
<span class="line"><span>16515846 -rw-r--r-- 2 paul paul 14 oct 12 09:50 hardlink_test.txt</span></span>
<span class="line"><span>16515846 -rw-r--r-- 2 paul paul 14 oct 12 09:50 test.txt</span></span></code></pre></div><p><code>ls</code> 的 <code>-i</code> 選項顯示一個文件的 “inode 數值”。“inode” 是分區表中的信息塊，它包含磁盤上文件或目錄的位置、上次修改的時間以及其它數據。如果兩個文件使用相同的 inode，那麼無論它們在目錄樹中的位置如何，它們在實際上都是相同的文件。</p><h3 id="軟鏈接" tabindex="-1">軟鏈接 <a class="header-anchor" href="#軟鏈接" aria-label="Permalink to “軟鏈接”">​</a></h3><p>軟鏈接，也稱為<ruby>符號鏈接<rt>symlink</rt></ruby>，它與硬鏈接是不同的：軟鏈接實際上是一個獨立的文件，它有自己的 inode 和它自己在磁盤上的小塊地方。但它只包含一小段數據，將操作系統指向另一個文件或目錄。</p><p>你可以使用 <code>ln</code> 的 <code>-s</code> 選項來創建一個軟鏈接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s test.txt softlink_test.txt</span></span></code></pre></div><p>這將在當前目錄中創建軟鏈接 <code>softlink_test.txt</code>，它指向 <code>test.txt</code>。</p><p>再次執行 <code>ls -li</code>，你可以看到兩種鏈接的不同之處：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -li</span></span>
<span class="line"><span>total 8</span></span>
<span class="line"><span>16515846 -rw-r--r-- 2 paul paul 14 oct 12 09:50 hardlink_test.txt</span></span>
<span class="line"><span>16515855 lrwxrwxrwx 1 paul paul 8 oct 12 09:50 softlink_test.txt -&gt; test.txt</span></span>
<span class="line"><span>16515846 -rw-r--r-- 2 paul paul 14 oct 12 09:50 test.txt</span></span></code></pre></div><p><code>hardlink_test.txt</code> 和 <code>test.txt</code> 包含一些文本並且<em>字面上</em>佔據相同的空間。它們使用相同的 inode 數值。與此同時，<code>softlink_test.txt</code> 佔用少得多，並且具有不同的 inode 數值，將其標記為完全不同的文件。使用 <code>ls</code> 的 <code>-l</code> 選項還會顯示軟鏈接指向的文件或目錄。</p><h3 id="為什麼要用鏈接" tabindex="-1">為什麼要用鏈接？ <a class="header-anchor" href="#為什麼要用鏈接" aria-label="Permalink to “為什麼要用鏈接？”">​</a></h3>`,16)),i("p",null,[s[11]||(s[11]=t("它們適用於",-1)),s[12]||(s[12]=i("strong",null,"帶有自己環境的應用程序",-1)),s[13]||(s[13]=t("。你的 Linux 發行版通常不會附帶你需要應用程序的最新版本。以優秀的 ",-1)),l(e,{href:"https://www.blender.org/"},{default:n(()=>[...s[10]||(s[10]=[t("Blender 3D",-1)])]),_:1}),s[14]||(s[14]=t(" 設計軟件為例，Blender 允許你創建 3D 靜態圖像以及動畫電影，人人都想在自己的機器上擁有它。問題是，當前版本的 Blender 至少比任何發行版中的自帶的高一個版本。",-1))]),i("p",null,[s[16]||(s[16]=t("幸運的是，",-1)),l(e,{href:"https://www.blender.org/download/"},{default:n(()=>[...s[15]||(s[15]=[t("Blender 提供可以開箱即用的下載",-1)])]),_:1}),s[17]||(s[17]=t("。除了程序本身之外，這些軟件包還包含了 Blender 需要運行的複雜的庫和依賴框架。所有這些數據和塊都在它們自己的目錄層次中。",-1))]),s[41]||(s[41]=a('<p>每次你想運行 Blender，你都可以 <code>cd</code> 到你下載它的文件夾並運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./blender</span></span></code></pre></div><p>但這很不方便。如果你可以從文件系統的任何地方，比如桌面命令啓動器中運行 <code>blender</code> 命令會更好。</p><p>這樣做的方法是將 <code>blender</code> 可執行文件鏈接到 <code>bin/</code> 目錄。在許多系統上，你可以通過將其鏈接到文件系統中的任何位置來使 <code>blender</code> 命令可用，就像這樣。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s /path/to/blender_directory/blender /home/&lt;username&gt;/bin</span></span></code></pre></div><p>你需要鏈接的另一個情況是<strong>軟件需要過時的庫</strong>。如果你用 <code>ls -l</code> 列出你的 <code>/usr/lib</code> 目錄，你會看到許多軟鏈接文件一閃而過。仔細看看，你會看到軟鏈接通常與它們鏈接到的原始文件具有相似的名稱。你可能會看到 <code>libblah</code> 鏈接到 <code>libblah.so.2</code>，你甚至可能會注意到 <code>libblah.so.2</code> 相應鏈接到原始文件 <code>libblah.so.2.1.0</code>。</p><p>這是因為應用程序通常需要安裝比已安裝版本更老的庫。問題是，即使新版本仍然與舊版本（通常是）兼容，如果程序找不到它正在尋找的版本，程序將會出現問題。為了解決這個問題，發行版通常會創建鏈接，以便挑剔的應用程序<strong>相信</strong>它找到了舊版本，實際上它只找到了一個鏈接並最終使用了更新的庫版本。</p><p>有些是和<strong>你自己從源代碼編譯的程序</strong>相關。你自己編譯的程序通常最終安裝在 <code>/usr/local</code> 下，程序本身最終在 <code>/usr/local/bin</code> 中，它在 <code>/usr/local/bin</code> 目錄中查找它需要的庫。但假設你的新程序需要 <code>libblah</code>，但 <code>libblah</code> 在 <code>/usr/lib</code> 中，這就是所有其它程序都會尋找到它的地方。你可以通過執行以下操作將其鏈接到 <code>/usr/local/lib</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s /usr/lib/libblah /usr/local/lib</span></span></code></pre></div><p>或者如果你願意，可以 <code>cd</code> 到 <code>/usr/local/lib</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /usr/local/lib</span></span></code></pre></div><p>然後使用鏈接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s ../lib/libblah</span></span></code></pre></div><p>還有幾十個案例證明軟鏈接是有用的，當你使用 Linux 更熟練時，你肯定會發現它們，但這些是最常見的。下一次，我們將看一些你需要注意的鏈接怪異。</p>',14)),i("p",null,[s[19]||(s[19]=t("通過 Linux 基金會和 edX 的免費 ",-1)),l(e,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:n(()=>[...s[18]||(s[18]=[t("“Linux 簡介”",-1)])]),_:1}),s[20]||(s[20]=t("課程瞭解有關 Linux 的更多信息。",-1))]),s[42]||(s[42]=i("hr",null,null,-1)),i("p",null,[s[22]||(s[22]=t("via: ",-1)),l(e,{href:"https://www.linux.com/blog/intro-to-linux/2018/10/linux-links-part-1"},{default:n(()=>[...s[21]||(s[21]=[t("https://www.linux.com/blog/intro-to-linux/2018/10/linux-links-part-1",-1)])]),_:1})]),i("p",null,[s[27]||(s[27]=t("作者：",-1)),l(e,{href:"https://www.linux.com/users/bro66"},{default:n(()=>[...s[23]||(s[23]=[t("Paul Brown",-1)])]),_:1}),s[28]||(s[28]=t(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[24]||(s[24]=[t("lujun9972",-1)])]),_:1}),s[29]||(s[29]=t(" 譯者：",-1)),l(e,{href:"https://github.com/MjSeven"},{default:n(()=>[...s[25]||(s[25]=[t("MjSeven",-1)])]),_:1}),s[30]||(s[30]=t(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[26]||(s[26]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[33]||(s[33]=t("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[31]||(s[31]=[t("LCTT",-1)])]),_:1}),s[34]||(s[34]=t(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:n(()=>[...s[32]||(s[32]=[t("Linux中國",-1)])]),_:1}),s[35]||(s[35]=t(" 榮譽推出",-1))])])}const C=d(u,[["render",g]]);export{y as __pageData,C as default};
